pub trait AccountRepository {            // port owned by the domain
    fn load(&self, id: AccountId) -> Result<Account, RepoError>;
    fn save(&self, account: &Account) -> Result<(), RepoError>;
}

pub fn transfer<A: AccountRepository>(accounts: &A, from: AccountId, to: AccountId,
                                      amount: Money) -> Result<(), TransferError> {
    let (mut source, mut target) = (accounts.load(from)?, accounts.load(to)?);
    source.withdraw(amount)?;
    target.deposit(amount);
    accounts.save(&source)?;
    accounts.save(&target)
}
